from pathlib import Path
import csv, json, hashlib
ROOT=Path(__file__).resolve().parents[1]
PAGES={r['locator']:r['text'] for r in map(json.loads,(ROOT/'evidence/S-001@1.jsonl').read_text().splitlines())}
rows=[]
def fact(n,statement,page,start,end=None,scope='Задано локальным учебным брифом; не эмпирическое подтверждение реального рынка.'):
    text=PAGES[f'page:{page}']; a=text.index(start)
    quote=text[a:text.index(end,a)+len(end)] if end else start
    assert quote in text
    rows.append([f'C-{n:03}','fact','active',statement,'S-001@1',f'page:{page}',quote,'',scope])
def inference(n,statement,basis,scope):
    rows.append([f'C-{n:03}','inference','active',statement,'','','',','.join(f'C-{i:03}' for i in basis),scope])
